\textcolor{darkgreen}{\textbf{Proof of $\phi(mn) = n\phi(m)$:}}

Let $m = p_1^{k_1} \cdots p_r^{k_r}$.

Since every prime of $n$ divides $m$, we can write $n = p_1^{j_1} \cdots p_r^{j_r}$
(some $j_i$ may be 0). Then:
\[
mn = p_1^{k_1+j_1} \cdots p_r^{k_r+j_r}
\]

Apply the product formula to both sides.

\textcolor{darkgreen}{\textbf{Left side:}}
\begin{align*}
\phi(mn) &= mn \prod_{i=1}^{r}\left(1 - \frac{1}{p_i}\right)
\end{align*}

\textcolor{darkgreen}{\textbf{Right side:}}
\begin{align*}
n\,\phi(m) &= n \cdot m \prod_{i=1}^{r}\left(1 - \frac{1}{p_i}\right) = mn \prod_{i=1}^{r}\left(1 - \frac{1}{p_i}\right)
\end{align*}

Since both sides equal $mn \displaystyle\prod_{i=1}^{r}\left(1 - \dfrac{1}{p_i}\right)$:
\[
\phi(mn) = n\,\phi(m) \quad \textcolor{green}{\checkmark}
\]

\textcolor{darkgreen}{\textbf{Proof of $\phi(n^2) = n\phi(n)$:}}

Setting $m = n$ (every prime of $n$ divides $n$ trivially):
\[
\phi(n^2) = \phi(n \cdot n) = n\,\phi(n)
\]

\textcolor{green}{\textbf{Conclusion:}} Both identities hold. \qed

Compute $\phi(1260^2)$ using the identity $\phi(n^2) = n\phi(n)$.

\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Factorize 1260.
\[
1260 = 2^2 \times 3^2 \times 5 \times 7
\]

\textbf{Step 2:} Compute $\phi(1260)$.
\begin{align*}
\phi(1260) &= \phi(2^2)\cdot\phi(3^2)\cdot\phi(5)\cdot\phi(7)\\
           &= 2 \times 6 \times 4 \times 6 = 288
\end{align*}

\textbf{Step 3:} Apply $\phi(n^2) = n\phi(n)$.
\[
\phi(1260^2) = 1260 \times \phi(1260) = 1260 \times 288 = \boxed{362880}
\]

Consistent with Example 18(d). \textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Proof:}}

For each $k \in \{1, 2, \ldots, n\}$, let $d = \gcd(n, k)$. Then $d \mid n$.

\textcolor{darkgreen}{\textbf{Step 1: Group by gcd value.}}

For each divisor $d$ of $n$, count the integers $k \in \{1, \ldots, n\}$ with
$\gcd(n,k) = d$.

Write $k = d\ell$ and $n = dm$. Then $\gcd(n,k) = d \iff \gcd(m, \ell) = 1$, where
$\ell \in \{1, \ldots, m\}$.

The number of such $\ell$ is $\phi(m) = \phi(n/d)$.

\textcolor{darkgreen}{\textbf{Step 2: Form the sum.}}

\[
\sum_{k=1}^{n} \gcd(n,k) = \sum_{d \mid n} d \cdot \#\{k : \gcd(n,k) = d\}
= \sum_{d \mid n} d \cdot \phi\!\left(\frac{n}{d}\right)
\]

\textcolor{green}{\textbf{Conclusion:}}
$\displaystyle\sum_{k=1}^{n}\gcd(n,k) = \sum_{d \mid n} d\,\phi\!\left(\frac{n}{d}\right)$.
\qed

For any positive integer $n$:
\[
\boxed{\sum_{d \mid n} \phi(d) = n}
\]

That is, the sum of Euler's phi function over all positive divisors of $n$ equals $n$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Examples:}}
\begin{itemize}[leftmargin=*]
    \item $n = 6$: $\phi(1) + \phi(2) + \phi(3) + \phi(6) = 1+1+2+2 = 6$
    \item $n = p$: $\phi(1) + \phi(p) = 1 + (p-1) = p$ \textcolor{green}{\checkmark}
    \item $n = p^k$: $\phi(1)+\phi(p)+\cdots+\phi(p^k) = 1+(p-1)+p(p-1)+\cdots+p^{k-1}(p-1) = p^k$
\end{itemize}

Verify $\sum_{d \mid p^3}\phi(d) = p^3$ for any prime $p$.

\textcolor{primaryblue}{\textbf{Solution:}}

Divisors of $p^3$: $1, p, p^2, p^3$.

\begin{align*}
\sum_{d \mid p^3}\phi(d) &= \phi(1) + \phi(p) + \phi(p^2) + \phi(p^3)\\
                          &= 1 + (p-1) + p(p-1) + p^2(p-1)\\
                          &= 1 + (p-1)(1 + p + p^2)\\
                          &= 1 + (p-1)\cdot\frac{p^3-1}{p-1}\\
                          &= 1 + p^3 - 1 = p^3 \quad \textcolor{green}{\checkmark}
\end{align*}

