For distinct primes $p$ and $q$, prove that $p^{q-1} + q^{p-1} \equiv 1 \pmod{pq}$.

\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1: Work modulo $p$.}

$q^{p-1} \equiv 1 \pmod{p}$ by FLT (since $p \nmid q$).

$p^{q-1} \equiv 0 \pmod{p}$.

Therefore: $p^{q-1} + q^{p-1} \equiv 0 + 1 = 1 \pmod{p}$.

\textbf{Step 2: Work modulo $q$.}

$p^{q-1} \equiv 1 \pmod{q}$ by FLT (since $q \nmid p$).

$q^{p-1} \equiv 0 \pmod{q}$.

Therefore: $p^{q-1} + q^{p-1} \equiv 1 + 0 = 1 \pmod{q}$.

\textbf{Step 3: Combine via CRT.}

$p^{q-1} + q^{p-1} \equiv 1 \pmod{p}$ and $\equiv 1 \pmod{q}$.

Since $\gcd(p,q) = 1$: $p^{q-1} + q^{p-1} \equiv 1 \pmod{pq}$. \textcolor{green}{\checkmark} \qed

\textbf{Numerical verification with $p=3, q=5$:}
\[
3^4 + 5^2 = 81 + 25 = 106 = 15 \times 7 + 1 \equiv 1 \pmod{15} \quad \textcolor{green}{\checkmark}
\]

Prove $a^{12} \equiv 1 \pmod{35}$ for all $a$ with $\gcd(a,35)=1$.

\textcolor{primaryblue}{\textbf{Solution:}}

Note $35 = 5 \times 7$.

\textbf{Step 1: Modulo 5.}

$\gcd(a,5) = 1$. By FLT: $a^4 \equiv 1 \pmod{5}$.

Since $12 = 4 \times 3$:
\[
a^{12} = (a^4)^3 \equiv 1^3 = 1 \pmod{5}
\]

\textbf{Step 2: Modulo 7.}

$\gcd(a,7) = 1$. By FLT: $a^6 \equiv 1 \pmod{7}$.

Since $12 = 6 \times 2$:
\[
a^{12} = (a^6)^2 \equiv 1^2 = 1 \pmod{7}
\]

\textbf{Step 3: Combine.}

$a^{12} \equiv 1 \pmod{5}$ and $a^{12} \equiv 1 \pmod{7}$, and $\gcd(5,7) = 1$.

\[
a^{12} \equiv 1 \pmod{35} \quad \textcolor{green}{\checkmark} \qed
\]

\textcolor{darkgreen}{\textbf{Proof:}}

Let $\{r_1, r_2, \ldots, r_{\phi(m)}\}$ be a Reduced Residue System modulo $m$.

\textcolor{darkgreen}{\textbf{Step 1: Show $\{ar_1, ar_2, \ldots, ar_{\phi(m)}\}$ is also an RRS.}}

Since $\gcd(a,m)=1$ and $\gcd(r_i,m)=1$:
\[
\gcd(ar_i, m) = 1 \quad \text{for all } i
\]

If $ar_i \equiv ar_j \pmod{m}$, then since $\gcd(a,m)=1$, we cancel $a$:
$r_i \equiv r_j \pmod{m}$, which forces $i = j$ (as the $r_i$ are distinct in the RRS).

So $\{ar_1, \ldots, ar_{\phi(m)}\}$ consists of $\phi(m)$ mutually incongruent integers,
each coprime to $m$ — an RRS. \textcolor{green}{\checkmark}

\textcolor{darkgreen}{\textbf{Step 2: Multiply all elements.}}

Since both sets are RRS mod $m$, their products are congruent modulo $m$:
\[
(ar_1)(ar_2)\cdots(ar_{\phi(m)}) \equiv r_1 r_2 \cdots r_{\phi(m)} \pmod{m}
\]
\[
a^{\phi(m)} \cdot r_1 r_2 \cdots r_{\phi(m)} \equiv r_1 r_2 \cdots r_{\phi(m)} \pmod{m}
\]

\textcolor{darkgreen}{\textbf{Step 3: Cancel $r_1 r_2 \cdots r_{\phi(m)}$.}}

Since each $r_i$ is coprime to $m$, their product is coprime to $m$. Cancel:
\[
a^{\phi(m)} \equiv 1 \pmod{m}
\]

\textcolor{green}{\textbf{Conclusion:}} For $\gcd(a,m)=1$, $a^{\phi(m)} \equiv 1 \pmod{m}$.
\qed

